#!/usr/bin/env node
// kar-citelock — Agensi skill script, generated by build.mjs in the sjgant80-hub/kar-citelock repository.
// The KERNEL block below is byte-identical to the logic of the live page (index.html) and to
// kernel.mjs, which the tests and the witness mutation gate run against. No network, no dependencies,
// writes no files: it reads the input you name and prints a JSON report to stdout.
// MIT licence.
// ---- KERNEL (from index.html) ----
/* ---------- constants ---------- */
var ALGO_VERSION = 'citelock-v1';
var NEAR_THRESHOLD = 0.90;
var ZERO_HASH = '0'.repeat(64);

/* ---------- text normalization ---------- */
function normalize(s){
  if (typeof s !== 'string') return '';
  var out = s;
  try { out = out.normalize('NFKC'); } catch(e){ /* older engines: skip */ }
  out = out
    .replace(/[‘’‛′]/g, "'")
    .replace(/[“”‟″]/g, '"')
    .replace(/[–—]/g, '-')
    .replace(/ /g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return out;
}

/* ---------- hashing ---------- */
function hasSubtle(){
  return !!(globalThis.crypto && globalThis.crypto.subtle && globalThis.crypto.subtle.digest);
}
async function sha256Hex(str){
  if (!hasSubtle()) throw new Error('Web Crypto (crypto.subtle) is not available in this context.');
  var enc = new TextEncoder().encode(str);
  var buf = await globalThis.crypto.subtle.digest('SHA-256', enc);
  var bytes = new Uint8Array(buf);
  var hex = '';
  for (var i=0;i<bytes.length;i++){ hex += bytes[i].toString(16).padStart(2,'0'); }
  return hex;
}

/* ---------- canonical JSON ---------- */
function canonicalize(obj){
  if (Array.isArray(obj)) return obj.map(canonicalize);
  if (obj && typeof obj === 'object'){
    var out = {};
    Object.keys(obj).sort().forEach(function(k){ out[k] = canonicalize(obj[k]); });
    return out;
  }
  return obj;
}
function canonicalJSON(obj){ return JSON.stringify(canonicalize(obj)); }

/* ---------- matching algorithm ---------- */
function levenshtein(a, b){
  var al = a.length, bl = b.length;
  if (al === 0) return bl;
  if (bl === 0) return al;
  var prev = new Array(bl+1);
  for (var j=0;j<=bl;j++) prev[j] = j;
  for (var i=1;i<=al;i++){
    var cur = new Array(bl+1);
    cur[0] = i;
    var ca = a.charCodeAt(i-1);
    for (var j2=1;j2<=bl;j2++){
      var cost = (ca === b.charCodeAt(j2-1)) ? 0 : 1;
      var del = prev[j2] + 1;
      var ins = cur[j2-1] + 1;
      var sub = prev[j2-1] + cost;
      cur[j2] = Math.min(del, ins, sub);
    }
    prev = cur;
  }
  return prev[bl];
}
function similarity(a, b){
  var maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1;
  return 1 - (levenshtein(a,b) / maxLen);
}

function findAnchor(quote, sourceNorm){
  var words = quote.split(' ').filter(function(w){ return w.length > 0; });
  var maxLen = Math.min(words.length, 8);
  for (var len = maxLen; len >= 3; len--){
    for (var start = 0; start + len <= words.length; start++){
      var phrase = words.slice(start, start+len).join(' ');
      var idx = sourceNorm.indexOf(phrase);
      if (idx !== -1){
        var quoteOffset = quote.indexOf(phrase);
        if (quoteOffset === -1) quoteOffset = 0;
        return { sourceIdx: idx, quoteOffset: quoteOffset, phrase: phrase };
      }
    }
  }
  return null;
}

function contextSnippet(norm, idx, len, pad){
  pad = pad || 30;
  var start = Math.max(0, idx - pad);
  var end = Math.min(norm.length, idx + len + pad);
  var s = norm.slice(start, end);
  if (start > 0) s = '…' + s;
  if (end < norm.length) s = s + '…';
  return s;
}

function verifyClaim(quoteRaw, src){
  var quote = normalize(quoteRaw);
  if (!quote) return { verdict:'EMPTY', similarity:0, excerpt:'' };
  if (!src || typeof src.norm !== 'string') return { verdict:'SOURCE_MISSING', similarity:0, excerpt:'' };

  var idx = src.norm.indexOf(quote);
  if (idx !== -1){
    return { verdict:'VERIFIED', similarity:1, excerpt: contextSnippet(src.norm, idx, quote.length) };
  }

  var anchor = findAnchor(quote, src.norm);
  if (!anchor){
    return { verdict:'NOT_FOUND', similarity:0, excerpt:'' };
  }

  var baseIdx = anchor.sourceIdx - anchor.quoteOffset;
  var best = null;
  for (var off = -20; off <= 20; off += 4){
    var start = Math.max(0, Math.min(src.norm.length, baseIdx + off));
    var end = Math.max(0, Math.min(src.norm.length, start + quote.length));
    var windowText = src.norm.slice(start, end);
    if (!windowText) continue;
    var sim = similarity(quote, windowText);
    if (!best || sim > best.sim) best = { sim: sim, idx: start };
  }
  if (!best) return { verdict:'NOT_FOUND', similarity:0, excerpt:'' };

  var verdict = best.sim >= NEAR_THRESHOLD ? 'NEAR_MATCH' : 'NOT_FOUND';
  return {
    verdict: verdict,
    similarity: best.sim,
    excerpt: contextSnippet(src.norm, best.idx, quote.length)
  };
}

/* ---------- sources, runs, receipts, ledger (shared by the page and the skill script) ---------- */
async function makeSource(label, text){
  var norm = normalize(text);
  return { label: label, norm: norm, hash: await sha256Hex(norm), length: norm.length };
}

function verifyAll(sources, claims){
  return claims.map(function(c){
    var src = sources.find(function(s){ return s.label === c.sourceLabel; });
    if (!src) return { verdict:'SOURCE_MISSING', similarity:0, excerpt:'' };
    return verifyClaim(c.quoteRaw, src);
  });
}

function summarizeVerdicts(results){
  var counts = {};
  results.forEach(function(r){ counts[r.verdict] = (counts[r.verdict]||0)+1; });
  return Object.keys(counts).sort().map(function(k){ return k + ':' + counts[k]; }).join('|');
}

function receiptPayload(sources, claims, results){
  var sortedSources = sources.slice().sort(function(a,b){ return a.label < b.label ? -1 : a.label > b.label ? 1 : 0; });
  var claimRows = claims.map(function(c, i){
    var r = results[i];
    return {
      source: c.sourceLabel,
      quote: normalize(c.quoteRaw),
      locator: c.locator || '',
      verdict: r.verdict,
      similarity: (typeof r.similarity === 'number' ? r.similarity : 0).toFixed(4)
    };
  }).sort(function(a,b){
    var ka = a.source + '\u0000' + a.quote + '\u0000' + a.locator;
    var kb = b.source + '\u0000' + b.quote + '\u0000' + b.locator;
    return ka < kb ? -1 : ka > kb ? 1 : 0;
  });
  return {
    algorithm: ALGO_VERSION,
    nearThreshold: NEAR_THRESHOLD.toFixed(2),
    sources: sortedSources.map(function(s){ return { label: s.label, sha256: s.hash, length: s.length }; }),
    claims: claimRows
  };
}

function chainHash(prevChainHash, receiptHash, summary){
  return sha256Hex(prevChainHash + ':' + receiptHash + ':' + summary);
}

async function verifyLedger(entries){
  var list = Array.isArray(entries) ? entries : [];
  var checks = [];
  var expectedPrev = ZERO_HASH;
  for (var i=0;i<list.length;i++){
    var e = list[i] || {};
    var prevMatches = (e.prevChainHash === expectedPrev);
    var chainMatches = ((await chainHash(e.prevChainHash, e.receiptHash, e.summary)) === e.chainHash);
    checks.push({ n: e.n, ok: prevMatches && chainMatches, prevMatches: prevMatches, chainMatches: chainMatches });
    expectedPrev = e.chainHash;
  }
  return { ok: Array.isArray(entries) && checks.every(function(c){ return c.ok; }), checks: checks };
}
// ---- CLI (from cli.mjs) ----
// cli.mjs — CiteLock on the command line. build.mjs bundles this with the KERNEL block of index.html into
// scripts/kar-citelock.mjs, the single file the Agensi skill runs. It reads one JSON input (a file, or `-`
// for stdin), verifies every claimed quote against its source and prints a JSON report.
// Exit 0 = every quote VERIFIED · 1 = at least one is not · 2 = the input could not be used.
import { readFileSync } from 'node:fs';

const USAGE = `usage: node kar-citelock.mjs <input.json | ->
input:  {"sources": [{"label": "…", "text": "…"} or {"label": "…", "file": "path/to/source.txt"}],
         "claims":  [{"source": "<a source label>", "quote": "…", "locator": "optional, e.g. p. 4"}]}
output: a JSON report on stdout. exit 0 = every quote VERIFIED, 1 = at least one is not, 2 = bad input`;

class InputError extends Error {}
const fail = (msg) => { throw new InputError(msg); };

function readText(path, what) {
  try { return readFileSync(path === '-' ? 0 : path, 'utf8'); }
  catch (e) { return fail(`cannot read ${what}: ${e.code || e.message}`); }
}

async function citelock(input) {
  if (!input || typeof input !== 'object' || !Array.isArray(input.sources) || !Array.isArray(input.claims)) {
    fail('input needs a "sources" array and a "claims" array');
  }
  const sources = [];
  for (const [i, s] of input.sources.entries()) {
    const label = typeof s?.label === 'string' ? s.label.trim() : '';
    if (!label) fail(`sources[${i}] needs a "label"`);
    if (sources.some((x) => x.label === label)) fail(`sources[${i}]: the label "${label}" is used twice`);
    const text = typeof s.text === 'string' ? s.text
      : typeof s.file === 'string' ? readText(s.file, `sources[${i}].file ${s.file}`)
      : fail(`sources[${i}] needs "text" or "file"`);
    if (!normalize(text)) fail(`sources[${i}] ("${label}") is empty`);
    sources.push(await makeSource(label, text));
  }
  const claims = input.claims.map((c, i) => {
    if (typeof c?.quote !== 'string' || !c.quote.trim()) fail(`claims[${i}] needs a non-empty "quote"`);
    if (typeof c.source !== 'string') fail(`claims[${i}] needs "source": the label of the source it quotes`);
    return { sourceLabel: c.source.trim(), quoteRaw: c.quote.trim(), locator: typeof c.locator === 'string' ? c.locator.trim() : '' };
  });
  if (!claims.length) fail('there are no claims to check');

  const results = verifyAll(sources, claims);
  const canonical = canonicalJSON(receiptPayload(sources, claims, results));
  const summary = summarizeVerdicts(results);
  const allVerified = results.every((r) => r.verdict === 'VERIFIED');
  return {
    exitCode: allVerified ? 0 : 1,
    report: {
      tool: 'kar-citelock',
      algorithm: ALGO_VERSION,
      verdict: allVerified ? 'ALL_VERIFIED' : 'NOT_ALL_VERIFIED',
      summary,
      results: claims.map((c, i) => ({
        source: c.sourceLabel,
        locator: c.locator,
        quote: normalize(c.quoteRaw),
        verdict: results[i].verdict,
        similarity: Number(results[i].similarity.toFixed(4)),
        excerpt: results[i].excerpt,
      })),
      sources: sources.map((s) => ({ label: s.label, sha256: s.hash, length: s.length })),
      receipt: { sha256: await sha256Hex(canonical), canonical },
    },
  };
}

async function main(args) {
  if (args.length !== 1 || args[0] === '-h' || args[0] === '--help') { process.stderr.write(USAGE + '\n'); return 2; }
  const raw = readText(args[0], args[0] === '-' ? 'stdin' : args[0]);
  let input;
  try { input = JSON.parse(raw); } catch (e) { fail(`the input is not valid JSON (${e.message})`); }
  const { exitCode, report } = await citelock(input);
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  return exitCode;
}

try {
  process.exitCode = await main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`kar-citelock: ${e instanceof InputError ? e.message : 'internal error: ' + (e && e.message)}\n`);
  process.exitCode = e instanceof InputError ? 2 : 3;
}
